            uris = self.prop_uris(atoms, key)
            got = self.solve(uris, frozenset(), K_CHILD, depth + 1)
            if not got:
                hit = self.memo.get((uris, frozenset()))
                if not (hit and hit[1] and key in required and types == {'object'}):
